import { loadFont as loadAnton } from "@remotion/google-fonts/Anton";
import { loadFont as loadSans } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";

// Solinha Distribuidora — v2 (retorno: "mais motion, intercalando imagem e fundo chapado com as cores do
// cliente"). Mesma voz e mesmos tempos da v1 (Solinha.tsx); agora as cenas se revezam entre vídeo da loja em tela cheia
// e fundo chapado amarelo ou azul-marinho, onde o vídeo entra num cartão que se mexe e o texto fica grande.
// Cada troca é diferente da anterior: círculo, chicote, painel subindo, clarão, faixa diagonal, zoom, íris, empurrão.
// Locução: trecho A entra em 0,15 s, trecho B em 12,75 s (pausa de 3,2 s só de produtos). O c13 (cigarros) fica de fora.

const { fontFamily: ANTON } = loadAnton("normal", { weights: ["400"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SANS } = loadSans("normal", { weights: ["700", "800"], subsets: ["latin", "latin-ext"] });

export const SOL2_FPS = 30;
export const SOL2_FRAMES = Math.round(26.5 * SOL2_FPS);
const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.7));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.42) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);

const NAVY = "#13213F";
const NAVY_L = "#1B2E58";
const NAVY_D = "#0B1530";
const YEL = "#FFD21F";
const YEL_D = "#F7C300";
const YEL_G = "linear-gradient(180deg, #FFE45C 0%, #FFD21F 45%, #F5B400 100%)";
const WA = "#25D366";
const IG_BLUE = "#0095F6";
const yel: React.CSSProperties = { backgroundImage: YEL_G, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent" };

// ───────── peças ─────────
const Video: React.FC<{ id: string; from: number; a: number; t: number; s0?: number; s1?: number; x0?: number; x1?: number; y0?: number; y1?: number; dur?: number; origin?: string }> = ({ id, from, a, t, s0 = 1.08, s1 = 1.2, x0 = 0, x1 = 0, y0 = 0, y1 = 0, dur = 1.5, origin = "50% 50%" }) => {
  const p = interpolate(t, [a, a + dur], [0, 1], { ...cl, easing: Easing.bezier(0.33, 0, 0.4, 1) });
  return (
    <Sequence from={Math.round((a - 0.25) * SOL2_FPS)} layout="none">
      <OffthreadVideo muted src={staticFile(`solinha/${id}.mp4`)} startFrom={Math.max(0, Math.round((from - 0.25) * SOL2_FPS))} style={{ width: "100%", height: "100%", objectFit: "cover", transformOrigin: origin, transform: `translate(${(x0 + (x1 - x0) * p).toFixed(1)}px, ${(y0 + (y1 - y0) * p).toFixed(1)}px) scale(${(s0 + (s1 - s0) * p).toFixed(4)})` }} />
    </Sequence>
  );
};
// vídeo em tela cheia, com câmera própria
const Full: React.FC<React.ComponentProps<typeof Video>> = (p) => (
  <AbsoluteFill style={{ overflow: "hidden", background: NAVY_D }}>
    <Video {...p} />
  </AbsoluteFill>
);
// fundo chapado: a cor do cliente e um círculo grande do mesmo tom girando devagar (movimento sem enfeite)
const Flat: React.FC<{ t: number; a: number; c: "y" | "n"; cx?: number; cy?: number }> = ({ t, a, c, cx = 50, cy = 40 }) => {
  const s = 0.85 + 0.25 * lin(t, a, a + 2.5);
  return (
    <AbsoluteFill style={{ background: c === "y" ? YEL : NAVY, overflow: "hidden" }}>
      <div style={{ position: "absolute", left: `${cx}%`, top: `${cy}%`, width: 1500, height: 1500, marginLeft: -750, marginTop: -750, borderRadius: 9999, background: c === "y" ? YEL_D : NAVY_L, transform: `translate(${(Math.sin(t * 0.9) * 60).toFixed(1)}px, ${(Math.cos(t * 0.7) * 50).toFixed(1)}px) scale(${s.toFixed(4)})` }} />
    </AbsoluteFill>
  );
};
// vídeo num cartão sobre o fundo chapado: entra girando com impulso e fica flutuando
const Card: React.FC<{ id: string; from: number; t: number; a: number; w: number; h: number; cx: number; cy: number; rot?: number; ring?: string; circle?: boolean; dur?: number }> = ({ id, from, t, a, w, h, cx, cy, rot = 0, ring = YEL, circle = false, dur = 1.5 }) => {
  const e = pop(t, a + 0.02, 0.5), f = k(t, a, 0.15);
  const r = rot + (1 - e) * (rot >= 0 ? 10 : -10) + Math.sin((t - a) * 1.8) * 1.2;
  return (
    <div style={{ position: "absolute", left: cx - w / 2, top: cy - h / 2, width: w, height: h, opacity: f, transform: `translateY(${((1 - e) * 220 + Math.sin((t - a) * 2.1) * 10).toFixed(1)}px) scale(${(0.6 + 0.4 * e).toFixed(4)}) rotate(${r.toFixed(2)}deg)` }}>
      <div style={{ width: "100%", height: "100%", borderRadius: circle ? 9999 : 44, overflow: "hidden", border: `10px solid ${ring}`, boxShadow: "0 30px 70px rgba(0,0,0,0.35)", background: NAVY_D }}>
        <Video id={id} from={from} a={a} t={t} s0={1.25} s1={1.08} dur={dur} />
      </div>
    </div>
  );
};
const Placa: React.FC<{ children: React.ReactNode; pad?: string; style?: React.CSSProperties }> = ({ children, pad = "18px 46px 22px", style }) => (
  <div style={{ background: NAVY, border: `6px solid ${YEL}`, borderRadius: 34, padding: pad, boxShadow: "0 18px 50px rgba(0,0,0,0.45)", display: "flex", flexDirection: "column", alignItems: "center", ...style }}>{children}</div>
);
// entra com impulso e fica parado; sai rápido antes do próximo
const enter = (t: number, at: number, out?: number, rot = -4): React.CSSProperties => {
  const e = pop(t, at, 0.42), f = k(t, at, 0.18);
  const o = out === undefined ? 0 : lin(t, out, out + 0.12);
  return { opacity: f * (1 - o), transform: `scale(${((0.55 + 0.45 * e) * (1 - 0.12 * o)).toFixed(4)}) rotate(${((1 - e) * rot).toFixed(2)}deg)` };
};
// título que sobe de trás de uma linha (máscara), batida de motion gráfico
const Rise: React.FC<{ t: number; at: number; children: React.ReactNode; style?: React.CSSProperties }> = ({ t, at, children, style }) => {
  const e = k(t, at, 0.38);
  return (
    <div style={{ overflow: "hidden", paddingTop: 8, ...style }}>
      <div style={{ transform: `translateY(${((1 - e) * 105).toFixed(1)}%) skewY(${((1 - e) * 6).toFixed(2)}deg)` }}>{children}</div>
    </div>
  );
};
const Center: React.FC<{ top: number; children: React.ReactNode; style?: React.CSSProperties }> = ({ top, children, style }) => (
  <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", ...style }}>{children}</div>
);
const Shade: React.FC<{ a?: number; from?: number }> = ({ a = 0.55, from = 40 }) => (
  <AbsoluteFill style={{ background: `linear-gradient(180deg, rgba(11,21,48,0) ${from - 30}%, rgba(11,21,48,${a}) ${from}%, rgba(11,21,48,${a}) ${from + 25}%, rgba(11,21,48,0) ${from + 55}%)` }} />
);
const Logo: React.FC<{ w: number; t: number; style?: React.CSSProperties }> = ({ w, t, style }) => (
  <div style={{ width: w, ...style }}>
    <Img src={staticFile("solinha/logo.png")} style={{ width: "100%", display: "block", filter: `drop-shadow(0 20px 40px rgba(0,0,0,0.45)) brightness(${(1 + 0.12 * Math.max(0, Math.sin(t * 2.2)) ** 6).toFixed(3)})` }} />
  </div>
);
const IgIcon: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s} viewBox="0 0 100 100">
    <defs>
      <radialGradient id="ig2" cx="30%" cy="107%" r="150%">
        <stop offset="0%" stopColor="#FDF497" />
        <stop offset="5%" stopColor="#FDF497" />
        <stop offset="45%" stopColor="#FD5949" />
        <stop offset="60%" stopColor="#D6249F" />
        <stop offset="90%" stopColor="#285AEB" />
      </radialGradient>
    </defs>
    <rect x="0" y="0" width="100" height="100" rx="26" fill="url(#ig2)" />
    <rect x="22" y="22" width="56" height="56" rx="17" fill="none" stroke="#fff" strokeWidth="7" />
    <circle cx="50" cy="50" r="13.5" fill="none" stroke="#fff" strokeWidth="7" />
    <circle cx="68.5" cy="31.5" r="4.5" fill="#fff" />
  </svg>
);
const WaIcon: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s} viewBox="0 0 100 100">
    <path d="M50 8 C27 8 9 26 9 48 C9 56 11 63 15 69 L10 91 L33 85 C38 88 44 89 50 89 C73 89 91 71 91 48 C91 26 73 8 50 8 Z" fill="#fff" />
    <path d="M37 28 C35 28 33 29 32 31 C30 34 28 38 30 44 C33 53 41 63 52 69 C58 72 62 72 65 70 C67 69 69 67 69 64 L69 61 C69 60 68 59 67 59 L59 55 C58 55 57 55 56 56 L53 60 C47 57 43 53 40 47 L44 44 C45 43 45 42 45 41 L41 32 C40 29 39 28 37 28 Z" fill={WA} />
  </svg>
);
const Pin: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s * 1.3} viewBox="0 0 100 130">
    <path d="M50 4 C25 4 8 22 8 46 C8 78 50 126 50 126 C50 126 92 78 92 46 C92 22 75 4 50 4 Z" fill={YEL} stroke={NAVY_D} strokeWidth="5" />
    <circle cx="50" cy="46" r="17" fill={NAVY} />
  </svg>
);
const Flash: React.FC<{ t: number; at: number; d?: number; a?: number }> = ({ t, at, d = 0.16, a = 0.7 }) => {
  const x = t < at ? 0 : 1 - lin(t, at, at + d);
  return x > 0 ? <AbsoluteFill style={{ background: "#FFF6CC", opacity: x * a }} /> : null;
};

// ───────── cenas ─────────
type Cena = { a: number; b: number; tr: "none" | "circle" | "whip" | "up" | "flash" | "diag" | "zoom" | "iris" | "left" | "down"; at?: [number, number]; draw: (t: number, a: number, b: number) => React.ReactNode };

const CENAS: Cena[] = [
  // 1 · gancho no freezer
  { a: 0, b: 1.25, tr: "none", draw: (t, a) => (
    <>
      <Full id="c04" from={0.4} a={a} t={t} s0={1.32} s1={1.12} y0={-40} y1={20} dur={1.3} />
      <Shade a={0.5} from={44} />
      <Center top={780}><div style={enter(t, 0.45, undefined, -5)}><Placa pad="18px 48px 24px"><div style={{ fontFamily: ANTON, fontSize: 104, lineHeight: 1.05, color: "#fff", whiteSpace: "nowrap" }}>BATEU A VONTADE</div></Placa></div></Center>
    </>
  ) },
  // 2 · chapado amarelo: de uma gelada?
  { a: 1.25, b: 2.6, tr: "circle", at: [540, 900], draw: (t, a) => (
    <>
      <Flat t={t} a={a} c="y" cy={70} />
      <Center top={250}>
        <Rise t={t} at={1.45}><div style={{ fontFamily: ANTON, fontSize: 150, lineHeight: 1.0, color: NAVY, whiteSpace: "nowrap" }}>DE UMA</div></Rise>
        <Rise t={t} at={1.72}><div style={{ fontFamily: ANTON, fontSize: 250, lineHeight: 1.0, color: NAVY, whiteSpace: "nowrap" }}>GELADA?</div></Rise>
      </Center>
      <Card id="c08" from={1.0} t={t} a={a + 0.05} w={720} h={820} cx={540} cy={1260} rot={-4} ring={NAVY} />
    </>
  ) },
  // 3 · cerveja (vídeo)
  { a: 2.6, b: 3.98, tr: "whip", draw: (t, a) => (
    <>
      <Full id="c06" from={1.4} a={a} t={t} s0={1.25} s1={1.08} x0={-40} x1={30} />
      <Shade a={0.42} from={64} />
      <Center top={1290}><div style={enter(t, 2.78, undefined, -5)}><Placa pad="10px 56px 16px"><div style={{ fontFamily: ANTON, fontSize: 132, lineHeight: 1.1, whiteSpace: "nowrap", ...yel }}>CERVEJA</div></Placa></div></Center>
    </>
  ) },
  // 4 · chapado azul: destilado
  { a: 3.98, b: 5.0, tr: "up", draw: (t, a) => (
    <>
      <Flat t={t} a={a} c="n" cy={35} />
      <Card id="c10" from={0.4} t={t} a={a + 0.04} w={740} h={900} cx={540} cy={720} rot={3} />
      <Center top={1290}><Rise t={t} at={4.09}><div style={{ fontFamily: ANTON, fontSize: 190, lineHeight: 1.0, whiteSpace: "nowrap", ...yel }}>DESTILADO</div></Rise></Center>
    </>
  ) },
  // 5 · energético (vídeo)
  { a: 5.0, b: 6.32, tr: "flash", draw: (t, a) => (
    <>
      <Full id="c05" from={0.6} a={a} t={t} s0={1.55} s1={1.36} origin="50% 8%" x0={30} x1={-30} />
      <Shade a={0.42} from={64} />
      <Center top={1290}><div style={enter(t, 5.11, undefined, 5)}><Placa pad="10px 56px 16px"><div style={{ fontFamily: ANTON, fontSize: 132, lineHeight: 1.1, whiteSpace: "nowrap", ...yel }}>ENERGÉTICO</div></Placa></div></Center>
    </>
  ) },
  // 6 · chapado amarelo: gelo, vídeo num círculo
  { a: 6.32, b: 7.15, tr: "diag", draw: (t, a) => (
    <>
      <Flat t={t} a={a} c="y" cy={30} />
      <Card id="c07" from={1.0} t={t} a={a + 0.04} w={760} h={760} cx={540} cy={760} rot={-6} ring={NAVY} circle />
      <Center top={1240}><Rise t={t} at={6.43}><div style={{ fontFamily: ANTON, fontSize: 280, lineHeight: 1.0, color: NAVY, whiteSpace: "nowrap" }}>GELO</div></Rise></Center>
    </>
  ) },
  // 7 · tem tudo aqui (vídeo)
  { a: 7.15, b: 8.22, tr: "zoom", draw: (t, a) => (
    <>
      <Full id="c03" from={4.0} a={a} t={t} s0={1.12} s1={1.26} x0={40} x1={-40} />
      <AbsoluteFill style={{ background: NAVY_D, opacity: 0.42 }} />
      <Center top={760}>
        <div style={enter(t, 7.27, undefined, -4)}>
          <div style={{ fontFamily: ANTON, fontSize: 180, lineHeight: 1.0, color: "#fff", whiteSpace: "nowrap", textShadow: "0 10px 40px rgba(0,0,0,0.6)" }}>TEM TUDO</div>
          <div style={{ fontFamily: ANTON, fontSize: 180, lineHeight: 1.0, whiteSpace: "nowrap", textAlign: "center", ...yel, filter: "drop-shadow(0 10px 30px rgba(0,0,0,0.6))" }}>AQUI!</div>
        </div>
      </Center>
    </>
  ) },
  // 8 · chapado azul: o logo, com um círculo amarelo abrindo atrás
  { a: 8.22, b: 9.55, tr: "iris", at: [540, 900], draw: (t, a) => {
    const c = pop(t, a + 0.02, 0.55);
    return (
      <>
        <Flat t={t} a={a} c="n" />
        <div style={{ position: "absolute", left: 540 - 430, top: 900 - 430, width: 860, height: 860, borderRadius: 9999, background: YEL, transform: `scale(${(c * (1 + 0.03 * Math.sin(t * 3))).toFixed(4)})` }} />
        <div style={{ position: "absolute", left: 540 - 470, top: 900 - 470, width: 940, height: 940, borderRadius: 9999, border: `6px solid ${YEL}`, opacity: 0.6 * c, transform: `scale(${(c * (1.04 + 0.04 * lin(t, a, 9.55))).toFixed(4)})` }} />
        <Center top={640}><div style={enter(t, 8.28, undefined, 6)}><Logo w={840} t={t} /></div></Center>
      </>
    );
  } },
  // 9 · pausa dos produtos: vídeo · amarelo · vídeo · azul
  { a: 9.55, b: 10.35, tr: "flash", draw: (t, a) => (
    <>
      <Full id="c09" from={1.0} a={a} t={t} s0={1.38} s1={1.12} dur={0.8} />
      <AbsoluteFill style={{ border: `12px solid ${YEL}` }} />
    </>
  ) },
  { a: 10.35, b: 11.15, tr: "left", draw: (t, a) => (
    <>
      <Flat t={t} a={a} c="y" cx={30} />
      <Card id="c02" from={2.6} t={t} a={a + 0.02} w={820} h={1340} cx={540} cy={960} rot={-3} ring={NAVY} dur={0.8} />
    </>
  ) },
  { a: 11.15, b: 11.95, tr: "flash", draw: (t, a) => (
    <>
      <Full id="c11" from={0.4} a={a} t={t} s0={1.35} s1={1.1} y0={30} y1={-20} dur={0.8} />
      <AbsoluteFill style={{ border: `12px solid ${YEL}` }} />
    </>
  ) },
  { a: 11.95, b: 12.75, tr: "down", draw: (t, a) => (
    <>
      <Flat t={t} a={a} c="n" cx={70} />
      <Card id="c03" from={0.2} t={t} a={a + 0.02} w={820} h={1340} cx={540} cy={960} rot={3} dur={0.8} />
    </>
  ) },
  // 10 · chapado amarelo: Instagram
  { a: 12.75, b: 16.25, tr: "up", draw: (t, a) => {
    const press = interpolate(t, [15.7, 15.8, 15.95], [0, 1, 0], cl);
    const done = t >= 15.82;
    const card = pop(t, 13.8, 0.5);
    const burst = lin(t, 15.82, 16.5);
    return (
      <>
        <Flat t={t} a={a} c="y" cy={58} />
        <Center top={250}>
          <Rise t={t} at={12.98}><div style={{ fontFamily: ANTON, fontSize: 132, lineHeight: 1.02, color: NAVY, whiteSpace: "nowrap" }}>SEGUE A GENTE</div></Rise>
          <div style={{ display: "flex", alignItems: "center", gap: 24, marginTop: 6, ...enter(t, 13.56, undefined, 4) }}>
            <IgIcon s={108} />
            <div style={{ fontFamily: ANTON, fontSize: 132, lineHeight: 1.02, color: NAVY, whiteSpace: "nowrap" }}>NO INSTAGRAM</div>
          </div>
        </Center>
        <div style={{ position: "absolute", left: 130, right: 130, top: 720, opacity: Math.min(1, card * 1.5), transform: `translateY(${((1 - card) * 160 + Math.sin(t * 1.8) * 16).toFixed(1)}px) scale(${(0.8 + 0.2 * card).toFixed(4)}) rotate(${(Math.sin(t * 1.2) * 1.4 + (1 - card) * -8).toFixed(2)}deg)` }}>
          <div style={{ background: "#FFFFFF", borderRadius: 44, padding: "46px 44px 48px", display: "flex", flexDirection: "column", alignItems: "center", boxShadow: "0 30px 80px rgba(19,33,63,0.35)", border: `8px solid ${NAVY}` }}>
            <div style={{ width: 230, height: 230, borderRadius: 999, padding: 7, background: "linear-gradient(45deg, #FDF497, #FD5949 45%, #D6249F 65%, #285AEB)" }}>
              <div style={{ width: "100%", height: "100%", borderRadius: 999, border: "6px solid #fff", background: NAVY, display: "flex", alignItems: "center", justifyContent: "center", overflow: "hidden" }}>
                <Img src={staticFile("solinha/logo.png")} style={{ width: "94%" }} />
              </div>
            </div>
            <div style={{ fontFamily: SANS, fontWeight: 800, fontSize: 52, color: "#111", marginTop: 28, whiteSpace: "nowrap", letterSpacing: "-0.01em", ...enter(t, 14.32, undefined, 0) }}>@suamarca</div>
            <div style={{ position: "relative", marginTop: 32, width: "100%", height: 116 }}>
              {done ? [0, 1, 2, 3, 4, 5, 6, 7].map((j) => {
                const ang = -170 + j * 23, r = 90 + burst * 200;
                return <div key={j} style={{ position: "absolute", left: "50%", top: "50%", width: 28, height: 28, borderRadius: 99, background: j % 2 ? NAVY : "#FD5949", opacity: 1 - burst, transform: `translate(${(Math.cos((ang * Math.PI) / 180) * r - 14).toFixed(1)}px, ${(Math.sin((ang * Math.PI) / 180) * r - 14).toFixed(1)}px) scale(${(1 - 0.5 * burst).toFixed(3)})` }} />;
              }) : null}
              <div style={{ position: "absolute", inset: 0, borderRadius: 22, background: done ? "#EFEFEF" : IG_BLUE, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: SANS, fontWeight: 800, fontSize: 52, color: done ? "#111" : "#FFF", transform: `scale(${(1 - 0.08 * press).toFixed(3)})`, opacity: k(t, 14.45, 0.3) }}>
                {done ? "Seguindo ✓" : "Seguir"}
              </div>
            </div>
          </div>
        </div>
      </>
    );
  } },
  // 11 · novidades e promoções (vídeo)
  { a: 16.25, b: 19.4, tr: "whip", draw: (t, a) => (
    <>
      <Full id="c14" from={3.2} a={a} t={t} s0={1.1} s1={1.3} y0={40} y1={-40} dur={3.2} />
      <AbsoluteFill style={{ background: NAVY_D, opacity: 0.3 }} />
      <Shade a={0.62} from={46} />
      <Center top={700}>
        <div style={{ fontFamily: SANS, fontWeight: 800, fontSize: 54, color: "#fff", letterSpacing: "0.04em", whiteSpace: "nowrap", textShadow: "0 6px 24px rgba(0,0,0,0.6)", ...enter(t, 16.33, undefined, 0) }}>FIQUE POR DENTRO DAS</div>
      </Center>
      {([["NOVIDADES", 17.35, 18.36], ["PROMOÇÕES", 18.53, undefined]] as const).map(([w, at, out], i) => (
        <Center key={w} top={800}>
          <div style={enter(t, at, out, i ? 5 : -5)}>
            <Placa pad="10px 56px 18px"><div style={{ fontFamily: ANTON, fontSize: 160, lineHeight: 1.1, whiteSpace: "nowrap", ...yel }}>{w}</div></Placa>
          </div>
        </Center>
      ))}
    </>
  ) },
  // 12 · chapado azul: o alfinete cai e a rua se desenha
  { a: 19.4, b: 21.5, tr: "iris", at: [540, 760], draw: (t, a) => {
    const drop = interpolate(t, [19.45, 19.85], [-420, 0], { ...cl, easing: Easing.bounce });
    const road = k(t, 19.6, 0.7);
    return (
      <>
