// máscara/movimento de entrada de cada cena (a cena nova entra por cima da anterior)
const entrada = (c: Cena, t: number): React.CSSProperties => {
  const e = interpolate(t, [c.a - 0.14, c.a + 0.16], [0, 1], { ...cl, easing: INOUT });
  if (e >= 1 || c.tr === "none") return {};
  const [x, y] = c.at ?? [540, 960];
  switch (c.tr) {
    case "circle":
    case "iris": return { clipPath: `circle(${(e * 1250).toFixed(0)}px at ${x}px ${y}px)` };
    case "whip": return { transform: `translateX(${((1 - e) * 1080).toFixed(1)}px)`, filter: `blur(${(Math.sin(e * Math.PI) * 18).toFixed(1)}px)` };
    case "left": return { transform: `translateX(${((1 - e) * -1080).toFixed(1)}px)` };
    case "up": return { transform: `translateY(${((1 - e) * 1920).toFixed(1)}px)` };
    case "down": return { transform: `translateY(${((1 - e) * -1920).toFixed(1)}px)` };
    case "diag": { const X = e * 1720; return { clipPath: `polygon(0 0, ${X.toFixed(0)}px 0, ${(X - 640).toFixed(0)}px 100%, 0 100%)` }; }
    case "zoom": return { opacity: Math.min(1, e * 1.5), transform: `scale(${(1.25 - 0.25 * e).toFixed(4)})`, filter: `blur(${((1 - e) * 18).toFixed(1)}px)` };
    case "flash": return {};
  }
  return {};
};

export const SolinhaV2: React.FC = () => {
  const t = useCurrentFrame() / SOL2_FPS;
  return (
    <AbsoluteFill style={{ background: NAVY_D }}>
      {CENAS.map((c, i) => {
        const fim = CENAS[i + 1] ? CENAS[i + 1].a + 0.17 : c.b;
        if (t < c.a - (c.tr === "flash" || c.tr === "none" ? 0 : 0.15) || t >= fim) return null;
        return (
          <AbsoluteFill key={i} style={entrada(c, t)}>
            {c.draw(t, c.a, c.b)}
          </AbsoluteFill>
        );
      })}
      {CENAS.filter((c) => c.tr === "flash").map((c) => <Flash key={c.a} t={t} at={c.a} d={0.16} a={0.8} />)}
    </AbsoluteFill>
  );
};

